create table public.curriculum_topics(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id),subject text not null,name text not null,unique(school_id,subject,name),unique(school_id,id));
create table public.question_topic_tags(school_id uuid not null,version_id uuid not null,question_id uuid not null,topic_id uuid not null,is_primary boolean not null default false,primary key(version_id,question_id,topic_id),foreign key(version_id,question_id)references public.exam_questions(version_id,id),foreign key(school_id,topic_id)references public.curriculum_topics(school_id,id));
create unique index primary_question_topic on public.question_topic_tags(version_id,question_id)where is_primary;
create table public.group_teachers(school_id uuid not null,group_id uuid not null,teacher_id uuid not null,primary key(group_id,teacher_id),foreign key(school_id,group_id)references public.groups(school_id,id),foreign key(school_id,teacher_id)references public.memberships(school_id,id));
create table public.query_teachers(school_id uuid not null,query_id uuid not null,teacher_id uuid not null,primary key(query_id,teacher_id),foreign key(school_id,query_id)references public.queries(school_id,id),foreign key(school_id,teacher_id)references public.memberships(school_id,id));
alter table public.curriculum_topics enable row level security;alter table public.question_topic_tags enable row level security;alter table public.group_teachers enable row level security;alter table public.query_teachers enable row level security;
create policy read_scope on public.curriculum_topics for select to authenticated using(school_id=private.school()and private.staff(school_id));
create policy read_scope on public.question_topic_tags for select to authenticated using(private.can_exam(version_id));
create policy read_scope on public.group_teachers for select to authenticated using(private.can_group(group_id));
create policy read_scope on public.query_teachers for select to authenticated using(private.can_query(query_id));
grant select on public.curriculum_topics,public.question_topic_tags,public.group_teachers,public.query_teachers to authenticated;
create or replace function private.group_teacher(g uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.groups gr where gr.id=g and gr.school_id=private.school()and private.role()='teacher'and not gr.archived and(gr.teacher_id=auth.uid()or exists(select 1 from public.group_teachers where group_id=g and teacher_id=auth.uid()))and private.assigned(gr.class_id,gr.subject))$$;
create or replace function private.can_query(q uuid)returns boolean language sql stable security definer set search_path='' as $$select not private.active_attempt()and exists(select 1 from public.queries qu where qu.id=q and qu.school_id=private.school()and((qu.student_id=auth.uid()and private.role()='student')or private.role()='teacher'and private.assigned(qu.class_id,qu.subject)and(qu.teacher_id=auth.uid()or exists(select 1 from public.query_teachers where query_id=q and teacher_id=auth.uid()))))$$;
create function public.manage_coteacher(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();c uuid;sub text;u uuid:=(p->>'teacherId')::uuid;i uuid:=(p->>'id')::uuid;begin perform private.require_access(s);if private.role()<>'administrator'then raise exception 'FORBIDDEN'using errcode='42501';end if;if p->>'kind'='group'then select class_id,subject into c,sub from public.groups where id=i and school_id=s;else select class_id,subject into c,sub from public.queries where id=i and school_id=s;end if;if not exists(select 1 from public.teacher_assignments a join public.memberships m on m.id=a.teacher_id where a.teacher_id=u and a.class_id=c and a.subject=sub and m.active and m.role='teacher')then raise exception 'TEACHER_UNASSIGNED';end if;if p->>'kind'='group'then insert into public.group_teachers values(s,i,u)on conflict do nothing;else insert into public.query_teachers values(s,i,u)on conflict do nothing;end if;perform private.audit(s,'resource.coteacher',i,p->>'reason');end$$;
create function public.archive_group(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare g public.groups;begin select * into g from public.groups where id=(p->>'id')::uuid;perform private.require_access(g.school_id);if private.role()<>'administrator'and not private.group_teacher(g.id)then raise exception 'FORBIDDEN'using errcode='42501';end if;update public.groups set archived=true where id=g.id;perform private.audit(g.school_id,'group.archived',g.id,p->>'reason');end$$;
create function public.save_feedback(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();u uuid:=(p->>'studentId')::uuid;c uuid:=(p->>'classId')::uuid;i uuid;begin perform private.require_access(s);if private.role()<>'teacher'or not private.assigned(c,p->>'subject')or not exists(select 1 from public.enrollments where student_id=u and class_id=c)then raise exception 'FORBIDDEN'using errcode='42501';end if;if p->>'visibility'='student'then insert into public.teacher_feedback(school_id,student_id,teacher_id,class_id,subject,body)values(s,u,auth.uid(),c,p->>'subject',p->>'body')returning id into i;else insert into private.support_notes(school_id,student_id,teacher_id,body)values(s,u,auth.uid(),p->>'body')returning id into i;end if;perform private.audit(s,'student.feedback',u);return i;end$$;
create function public.staff_notes(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare u uuid:=(p->>'studentId')::uuid;begin if not private.student_access(u)then raise exception 'FORBIDDEN'using errcode='42501';end if;return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'teacherId',teacher_id,'body',body,'createdAt',created_at)),'[]')from private.support_notes where student_id=u and school_id=private.school()and(teacher_id=auth.uid()or private.role()='administrator'));end$$;
create function public.create_topic(p jsonb)returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();i uuid;begin perform private.require_access(s,true);if not private.staff(s)then raise exception 'FORBIDDEN'using errcode='42501';end if;insert into public.curriculum_topics(school_id,subject,name)values(s,p->>'subject',p->>'name')on conflict(school_id,subject,name)do update set name=excluded.name returning id into i;return i;end$$;
create function public.conduct_counts(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare v uuid:=(p->>'versionId')::uuid;begin if not private.exam_teacher(v)then raise exception 'FORBIDDEN'using errcode='42501';end if;return(select jsonb_build_object('assigned',count(*),'notStarted',count(*)filter(where a.id is null),'started',count(a.id),'submitted',count(*)filter(where a.status='submitted'),'expired',count(*)filter(where a.status='expired'),'awaitingReview',count(*)filter(where exists(select 1 from private.grades where attempt_id=a.id and final_score is null)))from public.exam_recipients r left join public.attempts a on a.version_id=r.version_id and a.student_id=r.student_id where r.version_id=v);end$$;
create function public.edit_student(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare u uuid:=(p->>'studentId')::uuid;begin if not private.student_access(u)then raise exception 'FORBIDDEN'using errcode='42501';end if;update public.memberships set display_name=p->>'name'where id=u and role='student'and school_id=private.school();perform private.audit(private.school(),'student.profile.changed',u,p->>'reason',jsonb_build_object('displayName',p->>'name'));end$$;
create function public.discover_student(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();begin if not private.staff(s)then raise exception 'FORBIDDEN'using errcode='42501';end if;perform private.audit(s,'registry.discovery',null);return(select coalesce(jsonb_agg(x),'[]')from(select sr.student_id,m.active as access_active,l.display as login_id from public.student_registry sr join public.memberships m on m.id=sr.student_id left join private.login_identifiers l on l.user_id=sr.student_id and l.current where sr.school_id=s and sr.admission_number=p->>'admissionNumber' limit 5)x);end$$;
create function public.internal_teacher_report(p jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare u uuid:=coalesce((p->>'teacherId')::uuid,auth.uid());s uuid:=private.school();begin if not(private.role()='administrator'or private.role()='teacher'and u=auth.uid())or not exists(select 1 from public.memberships where id=u and school_id=s and role='teacher')then raise exception 'FORBIDDEN'using errcode='42501';end if;return jsonb_build_object('teacherId',u,'examCount',(select count(*)from public.exam_versions where teacher_id=u and school_id=s),'groupCount',(select count(*)from public.groups where teacher_id=u and school_id=s and not archived),'queryCount',(select count(*)from public.queries where teacher_id=u and school_id=s),'averageFirstResponseSeconds',(select avg(extract(epoch from first_response_at-started_at))from public.query_cycles where teacher_id=u and school_id=s),'originalTargetsMet',(select count(*)from public.query_cycles where teacher_id=u and school_id=s and solution_delivered_at<=original_due_at),'revisedTargetsMet',(select count(*)from public.query_cycles where teacher_id=u and school_id=s and solution_delivered_at<=due_at),'generatedAt',now());end$$;
revoke execute on function public.manage_coteacher(jsonb),public.archive_group(jsonb),public.save_feedback(jsonb),public.staff_notes(jsonb),public.create_topic(jsonb),public.conduct_counts(jsonb),public.edit_student(jsonb),public.discover_student(jsonb),public.internal_teacher_report(jsonb)from public,anon,authenticated;grant execute on function public.manage_coteacher(jsonb),public.archive_group(jsonb),public.save_feedback(jsonb),public.staff_notes(jsonb),public.create_topic(jsonb),public.conduct_counts(jsonb),public.edit_student(jsonb),public.discover_student(jsonb),public.internal_teacher_report(jsonb)to authenticated;
